WITH valid AS (SELECT id, account_type, LENGTH(account_type) AS account_type_length, COALESCE(status, 'NONE') AS status_filled FROM accounts WHERE opened_date > DATE '2024-03-23' AND status IS NOT NULL) SELECT CASE WHEN account_type_length >= 68 THEN 'LARGE' ELSE 'SMALL' END AS account_type_length_tier, COUNT(CASE WHEN account_type = 'CREDIT' THEN 1 END) AS credit_count, SUM(CASE WHEN account_type = 'CREDIT' THEN account_type_length ELSE 0 END) AS credit_account_type_length, ROUND(AVG(account_type_length), 2) AS avg_account_type_length, COUNT(DISTINCT id) AS distinct_ids, MAX(account_type_length) FILTER (WHERE account_type = 'CHECKING') AS checking_max_account_type_length, COUNT_IF(account_type = 'CHECKING') AS checking_events FROM valid GROUP BY account_type_length_tier HAVING ROUND(AVG(account_type_length), 2) < 0;
